static const long CMS_DER_len = 1268;

static const unsigned char CMS_CONTENT[] = {
  0x54,0x68,0x65,0x20,0x71,0x75,0x69,0x63,0x6b,0x20,0x62,0x72,
  0x6f,0x77,0x6e,0x20,0x66,0x6f,0x78,0x20,0x6a,0x75,0x6d,0x70,
  0x73,0x20,0x6f,0x76,0x65,0x72,0x20,0x74,0x68,0x65,0x20,0x6c,
  0x61,0x7a,0x79,0x20,0x64,0x6f,0x67,0x2e,0x0a,
};
static const long CMS_CONTENT_len = 45;

static const char B64_IN[] = "aGVsbG8sIHJrdGNyeXB0byE=";
static const long B64_IN_len = 24;

static const unsigned char B64_OUT[] = {
  0x68,0x65,0x6c,0x6c,0x6f,0x2c,0x20,0x72,0x6b,0x74,0x63,0x72,
  0x79,0x70,0x74,0x6f,0x21,
};
static const long B64_OUT_len = 17;

/* ========================================================================= */

static int g_fail = 0;
static void check(const char *name, int ok){
  printf("%s %s\n", ok ? "OK  " : "FAIL", name);
  if(!ok) g_fail = 1;
}

int main(void){
  unsigned char buf[8192];
  unsigned char der[8192];
  intptr_t n;

  /* ---- 1. base64_decode ------------------------------------------------ */
  n = rktcrypto_base64_decode(B64_IN, B64_IN_len, buf);
  check("base64_decode known vector length",
        n == B64_OUT_len);
  check("base64_decode known vector bytes",
        n == B64_OUT_len && memcmp(buf, B64_OUT, (size_t)B64_OUT_len) == 0);

  /* whitespace/newlines must be ignored */
  {
    const unsigned char ws[] = "aGVsbG8s\n IHJrdGNy\r\n eXB0byE=\n";
    n = rktcrypto_base64_decode(ws, (intptr_t)sizeof(ws)-1, buf);
    check("base64_decode ignores whitespace",
          n == B64_OUT_len && memcmp(buf, B64_OUT, (size_t)B64_OUT_len) == 0);
  }
  /* malformed input (invalid alphabet char) must be rejected with -1 */
  {
    const unsigned char bad[] = "aGVs!bG8=";
    n = rktcrypto_base64_decode(bad, (intptr_t)sizeof(bad)-1, buf);
    check("base64_decode rejects malformed input", n == -1);
  }

  /* ---- 2. pem_to_der --------------------------------------------------- */
  n = rktcrypto_pem_to_der(RSA_CERT_PEM, RSA_CERT_PEM_len, der);
  check("pem_to_der RSA cert length matches DER",
        n == RSA_CERT_DER_len);
  check("pem_to_der RSA cert bytes match DER",
        n == RSA_CERT_DER_len && memcmp(der, RSA_CERT_DER, (size_t)RSA_CERT_DER_len) == 0);

  n = rktcrypto_pem_to_der(EC_CERT_PEM, EC_CERT_PEM_len, der);
  check("pem_to_der EC cert bytes match DER",
        n == EC_CERT_DER_len && memcmp(der, EC_CERT_DER, (size_t)EC_CERT_DER_len) == 0);

  /* ---- 3. x509_verify_selfsigned --------------------------------------- */
  check("x509 verify valid RSA-2048/SHA256 self-signed",
        rktcrypto_x509_verify_selfsigned(RSA_CERT_DER, RSA_CERT_DER_len) == 1);
  check("x509 verify valid ECDSA-P256/SHA256 self-signed",
        rktcrypto_x509_verify_selfsigned(EC_CERT_DER, EC_CERT_DER_len) == 1);

  /* NEGATIVE: flip a byte in the RSA signature (last byte of the cert DER,
     which lies inside signatureValue). A correct verifier must REJECT. */
  memcpy(buf, RSA_CERT_DER, (size_t)RSA_CERT_DER_len);
  buf[RSA_CERT_DER_len - 1] ^= 0x01;
  check("x509 REJECTS tampered RSA signature",
        rktcrypto_x509_verify_selfsigned(buf, RSA_CERT_DER_len) == 0);

  /* NEGATIVE: flip a byte deep inside the TBSCertificate (offset 20 is content
     -> changes the signed hash). Must REJECT. */
  memcpy(buf, RSA_CERT_DER, (size_t)RSA_CERT_DER_len);
  buf[20] ^= 0x01;
  check("x509 REJECTS tampered RSA TBS",
        rktcrypto_x509_verify_selfsigned(buf, RSA_CERT_DER_len) == 0);

  /* NEGATIVE: flip a byte in the ECDSA signature (last byte of cert DER). */
  memcpy(buf, EC_CERT_DER, (size_t)EC_CERT_DER_len);
  buf[EC_CERT_DER_len - 1] ^= 0x01;
  check("x509 REJECTS tampered ECDSA signature",
        rktcrypto_x509_verify_selfsigned(buf, EC_CERT_DER_len) == 0);

  /* NEGATIVE: flip a byte inside the ECDSA TBSCertificate. */
  memcpy(buf, EC_CERT_DER, (size_t)EC_CERT_DER_len);
  buf[20] ^= 0x01;
  check("x509 REJECTS tampered ECDSA TBS",
        rktcrypto_x509_verify_selfsigned(buf, EC_CERT_DER_len) == 0);

  /* ---- 4. cms_verify --------------------------------------------------- */
  check("cms_verify valid RSA/SHA256 SignedData",
        rktcrypto_cms_verify(CMS_DER, CMS_DER_len) == 1);

  /* NEGATIVE: flip a byte in the CMS signature (last byte of DER lies inside
     the SignerInfo signature OCTET STRING). Must REJECT. */
  memcpy(buf, CMS_DER, (size_t)CMS_DER_len);
  buf[CMS_DER_len - 1] ^= 0x01;
  check("cms_verify REJECTS tampered signature",
        rktcrypto_cms_verify(buf, CMS_DER_len) == 0);

  /* NEGATIVE: tamper the embedded content. Locate the exact content bytes in
     the DER and flip one; the messageDigest signed-attr check must REJECT. */
  {
    memcpy(buf, CMS_DER, (size_t)CMS_DER_len);
    /* find the embedded content substring inside the CMS DER and flip a byte */
    long i, pos = -1;
    for(i = 0; i + CMS_CONTENT_len <= CMS_DER_len; i++){
      if(memcmp(buf + i, CMS_CONTENT, (size_t)CMS_CONTENT_len) == 0){ pos = i; break; }
    }
    check("cms tamper: located embedded content in DER", pos >= 0);
    if(pos >= 0) buf[pos] ^= 0x01;
    check("cms_verify REJECTS tampered content",
          rktcrypto_cms_verify(buf, CMS_DER_len) == 0);
  }

  printf("%s\n", g_fail ? "FAILURES" : "ALL PASS");
  return g_fail ? 1 : 0;
}
